SysDataModelXML.SQLClear:
DECLARE @ROUCOD VARCHAR(30) = '{0}' DECLARE @ROUTYP VARCHAR(30) = '{1}' DECLARE @ITMNO VARCHAR(30) = '{2}' DECLARE @ROUALT VARCHAR(30) = '{3}' DECLARE @ROUOPE VARCHAR(30) = '{4}' DECLARE @CUSCOD VARCHAR(30) = '{5}' DECLARE @INTSPE VARCHAR(30) = '{6}' DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'
IF (@ROUTYP='IMI') AND NOT EXISTS (SELECT 1 FROM QAROU WHERE ROUCOD=@ROUCOD) BEGIN -- CREATE QAROU INSERT INTO QAROU ( ROUCOD , ITMNO , ROUALT , ROUOPE , CUSCOD , ROUTYP , INTSPEC , HEATTITLE , CREUSR , CRETIM ) VALUES ( @ROUCOD , @ITMNO , @ROUALT , @ROUOPE , @CUSCOD --CUSCOD , @ROUTYP , '' --INTSPE , '' --HEATTITLE , @USER , GETDATE() ); END;
IF @ROUTYP IN ('SFC', 'ICC', 'INE') AND @ROUCOD = '' BEGIN -- 工艺路线不存在时，执行自动创建 IF @ROUTYP = 'SFC' SET @ROUCOD = CONCAT_WS('-', @ITMNO, @ROUALT, @ROUOPE) ELSE IF @ROUTYP IN ('ICC') SET @ROUCOD = @ITMNO ELSE IF @ROUTYP IN ('INC', 'INE') SET @ROUCOD = CONCAT_WS('-', @ROUTYP, @ITMNO)
-- CREATE QAROU INSERT INTO QAROU ( ROUCOD , ITMNO , ROUALT , ROUOPE , CUSCOD , ROUTYP , INTSPEC , HEATTITLE , CREUSR , CRETIM ) VALUES ( @ROUCOD , @ITMNO , @ROUALT , @ROUOPE , @CUSCOD --CUSCOD , @ROUTYP , @INTSPE --INTSPE , '' --HEATTITLE , @USER , GETDATE() );
UPDATE QAROU SET INTSPEC=@INTSPE WHERE ROUCOD=@ROUCOD AND ROUTYP='SFC';
END
